begin;
\ir _helpers.psql
select plan(30);

-- Fractional index parity with rocicorp/fractional-indexing (values generated by the JS library).
select is(
  array[app.sort_key_after('a0'), app.sort_key_after('az'), app.sort_key_after('Zz'), app.sort_key_after('a0V'),
        app.sort_key_after('b00'), app.sort_key_before('a0'), app.sort_key_before('a1'), app.sort_key_before('b00'),
        app.sort_key_before('a0V'), app.sort_key_before('Zz'), app.sort_key_before('Y00')],
  array['a1', 'b00', 'a0', 'a1', 'b01', 'Zz', 'a0', 'az', 'a0', 'Zy', 'Xzzz'],
  'SQL sort keys match the JS library'
);

select tests.create_user('alice');
select tests.create_user('bob');
select tests.create_user('mallory');
select tests.authenticate_as('alice');
select public.create_workspace('Acme', 't-acme', 'Engineering', 'ENG', 'software');
select tests.clear_authentication();
insert into public.workspace_members (workspace_id, user_id, role)
select id, tests.uid('bob'), 'member'::public.workspace_role from public.workspaces where slug = 't-acme';
create temp table ctx on commit drop as
  select w.id as ws, t.id as team from public.workspaces w join public.teams t on t.workspace_id = w.id
  where w.slug = 't-acme';
grant select on ctx to authenticated;

-- Creation ----------------------------------------------------------------------
select tests.authenticate_as('alice');
insert into public.tasks (workspace_id, team_id, title)
select ws, team, 'First task' from ctx;
insert into public.tasks (workspace_id, team_id, title, priority)
select ws, team, 'Second task', 1 from ctx;

select is((select array_agg(number order by number) from public.tasks), array[1, 2], 'identifiers are sequential per team');
select is((select creator_id from public.tasks where number = 1), tests.uid('alice'), 'creator is the caller');
select is(
  (select s.name from public.tasks t join public.statuses s on s.id = t.status_id where t.number = 1),
  'Todo', 'default status is the first unstarted status'
);
select ok(
  (select sort_key from public.tasks where number = 2) < (select sort_key from public.tasks where number = 1),
  'new tasks without a key go to the top'
);
select is((select count(*)::int from public.task_subscribers), 2, 'creators are subscribed');
select is((select count(*)::int from public.activity where kind = 'task.created'), 2, 'creation is logged');
select throws_ok(
  $$ insert into public.tasks (workspace_id, team_id, title, number) select ws, team, 'x', 99 from ctx $$,
  '42501', null, 'number is not client-writable'
);
select throws_ok(
  $$ update public.tasks set team_id = gen_random_uuid() where number = 1 $$,
  '42501', null, 'team is not client-writable'
);

-- Status timestamps -----------------------------------------------------------
update public.tasks set status_id = (select id from public.statuses where name = 'Done') where number = 1;
select isnt((select completed_at from public.tasks where number = 1), null, 'completed_at is set by category');
update public.tasks set status_id = (select id from public.statuses where name = 'Todo') where number = 1;
select is((select completed_at from public.tasks where number = 1), null, 'completed_at clears when reopened');

-- Descriptions --------------------------------------------------------------------
update public.tasks
set description = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hello search"}]}]}'
where number = 1;
select is((select description_text from public.tasks where number = 1), 'Hello search', 'description text is derived');
select throws_ok(
  $$ update public.tasks set description = '{"type":"html","content":"<script>"}' where number = 1 $$,
  '23514', null, 'only editor documents are accepted'
);

-- Sub-tasks -------------------------------------------------------------------------
insert into public.tasks (workspace_id, team_id, title, parent_id)
select ws, team, 'Child', (select id from public.tasks where number = 1) from ctx;
insert into public.tasks (workspace_id, team_id, title, parent_id)
select ws, team, 'Grandchild', (select id from public.tasks where title = 'Child') from ctx;
select throws_ok(
  $$ insert into public.tasks (workspace_id, team_id, title, parent_id)
     select ws, team, 'Too deep', (select id from public.tasks where title = 'Grandchild') from ctx $$,
  '23514', null, 'nesting is limited to 3 levels'
);
select throws_ok(
  $$ update public.tasks set parent_id = (select id from public.tasks where title = 'Grandchild') where number = 1 $$,
  '23514', null, 'cycles are rejected'
);

-- Assignees, notifications ---------------------------------------------------------
insert into public.task_assignees (task_id, workspace_id, user_id)
select (select id from public.tasks where number = 2), ws, tests.uid('bob') from ctx;
select is((select count(*)::int from public.notifications), 0, 'actors are never notified');

select tests.authenticate_as('bob');
select is((select kind from public.notifications), 'assigned', 'assignees are notified');
insert into public.comments (workspace_id, task_id, body)
select ws, (select id from public.tasks where number = 2),
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On it"}]}]}' from ctx;
select is((select author_id from public.comments), tests.uid('bob'), 'comment author is the caller');

select tests.authenticate_as('alice');
select is((select kind from public.notifications where user_id = tests.uid('alice')), 'comment', 'subscribers hear about comments');
insert into public.comments (workspace_id, task_id, body)
select ws, (select id from public.tasks where number = 2),
  jsonb_build_object('type', 'doc', 'content', jsonb_build_array(jsonb_build_object('type', 'paragraph', 'content',
    jsonb_build_array(jsonb_build_object('type', 'mention', 'attrs', jsonb_build_object('id', tests.uid('bob'))))))) from ctx;
select tests.authenticate_as('bob');
select is(
  (select kind || ':' || event_count from public.notifications),
  'mention:2', 'bursts coalesce into one notification and keep the most important kind'
);
select tests.authenticate_as('alice');

-- Soft delete and restore ------------------------------------------------------------
select lives_ok($$ select public.delete_tasks(array[(select id from public.tasks where number = 1)]) $$, 'tasks can be deleted');
select is((select count(*)::int from public.tasks where title in ('First task', 'Child', 'Grandchild')), 0, 'deleting hides sub-tasks too');
select tests.clear_authentication();
create temp table deleted on commit drop as select id from public.tasks where number = 1 and workspace_id = (select ws from ctx);
grant select on deleted to authenticated;
select tests.authenticate_as('alice');
select is((select public.restore_tasks(array[(select id from deleted)])), 3, 'restore brings back the whole tree');

-- Isolation --------------------------------------------------------------------------
select tests.authenticate_as('mallory');
select is((select count(*)::int from public.tasks), 0, 'outsiders see no tasks');
select is((select count(*)::int from public.comments), 0, 'outsiders see no comments');
select is((select count(*)::int from public.activity), 0, 'outsiders see no activity');
select throws_ok(
  $$ insert into public.tasks (workspace_id, team_id, title) select ws, team, 'Injected' from ctx $$,
  '42501', null, 'outsiders cannot create tasks in another workspace'
);
select is((select public.delete_tasks(array(select id from public.tasks))) is not null, true, 'delete_tasks ignores invisible ids');
select tests.clear_authentication();
select is((select count(*)::int from public.tasks where deleted_at is not null and workspace_id = (select ws from ctx)), 0, 'nothing was deleted by the outsider');

-- Search -------------------------------------------------------------------------------
select tests.authenticate_as('alice');
select is((select subtitle from public.search((select ws from ctx), 'ENG-2') limit 1), 'ENG-2', 'identifier search ranks first');

select * from finish();
rollback;
